// Preprocessor support for NEOMCP_DESCRIBE and NEOMCP_DESCRIBE_ENUM (see describe.h for what they do).
//
// The macros count their arguments by position and then call the macro made for exactly that many entries. This
// works with every compiler's default preprocessor, including the traditional MSVC one: the argument lists are
// forwarded only inside NEOMCP_DETAIL_EXPAND, which makes that preprocessor split them again, and nothing here
// relies on __VA_OPT__. A macro invocation may carry at most 127 arguments there, which is what limits the number
// of entries: the counting call passes the entries plus one placeholder per possible count, so 32 members
// (two arguments each) and 63 enumerators are the largest lists that fit.
#pragma once

#define NEOMCP_DETAIL_EXPAND(x) x

// One member of a described struct.
#define NEOMCP_DETAIL_FIELD(Type, member, description) neomcp::field(&Type::member, #member, description)

// NEOMCP_DETAIL_PAIRS_<n>(Type, member1, description1, ..., member<n>, description<n>) is the comma separated list of fields.
#define NEOMCP_DETAIL_PAIRS_1(T, m1, d1) NEOMCP_DETAIL_FIELD(T, m1, d1)
#define NEOMCP_DETAIL_PAIRS_2(T, m1, d1, m2, d2) NEOMCP_DETAIL_FIELD(T, m1, d1), NEOMCP_DETAIL_PAIRS_1(T, m2, d2)
#define NEOMCP_DETAIL_PAIRS_3(T, m1, d1, m2, d2, m3, d3) NEOMCP_DETAIL_FIELD(T, m1, d1), NEOMCP_DETAIL_PAIRS_2(T, m2, d2, m3, d3)
